# Ingest fast paths must not change the stored bytes. Expected hashes were
# generated by the code before the fast paths were added (n = 1200 rows,
# threads = 2); every input type variant must reproduce them exactly.
ingest_variants <- function(n) {
  set.seed(5)
  chrs <- rep(c("1","2","10","22","X","Y"), length.out = n)
  pos <- sample.int(5e6, n) + 1000L
  b <- c("A","C","G","T"); r <- sample(4, n, TRUE); a <- (r + sample(3, n, TRUE) - 1L) %% 4L + 1L
  se <- runif(n, .01, .1); beta <- rnorm(n, 0, .05)
  base <- data.frame(chromosome = chrs, base_pair_location = pos,
    reference_allele = b[r], alternate_allele = b[a], effect_allele = b[a], other_allele = b[r],
    beta = beta, standard_error = se, effect_allele_frequency = runif(n, .05, .95),
    p_value = 2*pnorm(-abs(beta/se)), stringsAsFactors = FALSE)
  messy <- function(x) { i <- seq(1, n, 7); x[i] <- tolower(x[i]); j <- seq(2, n, 11); x[j] <- paste0(" ", x[j], " "); x }
  v <- list(base = base)
  d <- base; d$base_pair_location <- as.double(d$base_pair_location); v$pos_double <- d
  d <- base; d$base_pair_location <- as.character(d$base_pair_location); v$pos_char <- d
  d <- base; d$base_pair_location <- factor(d$base_pair_location); v$pos_factor <- d
  d <- base; for (f in c("reference_allele","alternate_allele","effect_allele","other_allele")) d[[f]] <- messy(d[[f]]); v$messy_alleles <- d
  d <- base; for (f in c("reference_allele","alternate_allele","effect_allele","other_allele")) d[[f]] <- factor(messy(d[[f]])); v$factor_alleles <- d
  d <- base; d$chromosome <- paste0(rep(c("chr","Chr",""), length.out = n), d$chromosome); v$chr_prefix <- d
  d <- base; d$chromosome <- factor(paste0("chr", d$chromosome)); v$chr_factor <- d
  d <- base; d$chromosome <- ifelse(d$chromosome %in% c("X"), "23", ifelse(d$chromosome == "Y", "24", d$chromosome)); v$chr_alias <- d
  d <- base; d$chromosome <- ifelse(d$chromosome %in% as.character(1:22), d$chromosome, "1"); d$chromosome <- as.integer(d$chromosome); v$chr_integer <- d
  d <- base; d$p_value <- as.character(d$p_value); v$p_char <- d
  d <- base; d$p_value[seq(3, n, 13)] <- NA; v$p_na <- d
  d <- base; d$p_value[seq(3, n, 13)] <- NA; d$p_value <- as.character(d$p_value); d$p_value[seq(5, n, 17)] <- "NA"; d$p_value[seq(6, n, 19)] <- "."; v$p_char_na <- d
  d <- base; d$base_pair_location[c(2, 9)] <- c(1e9, 0); v$pos_bad <- d
  d <- base; d$base_pair_location <- as.double(d$base_pair_location); d$base_pair_location[c(2,9)] <- c(1000.5, NA); v$pos_frac_na <- d
  d <- base; d$chromosome[4] <- "MT"; d$reference_allele[6] <- "AT"; d$alternate_allele[8] <- NA; v$bad_rows <- d
  d <- base; d$chromosome[3] <- NA; v$chr_na <- d
  v
}

