ingest_store_hashes <- function(data, qc) {
  path <- tempfile("ingest-fastpath-", fileext = ".cpr")
  on.exit(unlink(path, recursive = TRUE), add = TRUE)
  # The pinned payload hashes were recorded with the Z9/SE6 profile; the
  # ingest paths under test are independent of the quantisation profile.
  old <- options(CompreSSoR.native_profile = "z9/eaf8/se6")
  on.exit(options(old), add = TRUE)
  store <- suppressWarnings(compress_sumstats(data, path, qc = qc, overwrite = TRUE, pvalue_order = FALSE,
                                              threads = 2L))
  list(rows = store$manifest$n_rows,
       payload = store$manifest$integrity$payload_sha256,
       canonical = store$manifest$integrity$canonical_sha256)
}

test_that("ingest type variants reproduce pre-optimisation store hashes", {
  skip_if_not(CompreSSoR:::pcodec_native_available(),
              "native Pcodec backend is not built")
  variants <- ingest_variants(1200L)
  for (k in seq_len(nrow(ingest_expected))) {
    e <- ingest_expected[k, ]
    got <- ingest_store_hashes(variants[[e$variant]], e$qc)
    label <- paste(e$variant, e$qc)
    expect_identical(as.integer(got$rows), as.integer(e$rows), label = label)
    # Pin the stored data by payload hash. The canonical manifest hash embeds a
    # serialize() digest of the input, which differs across R versions (and for
    # factor columns across sessions), so it is not pinned here.
    expect_identical(got$payload, e$payload, label = label)
  }
})

test_that("equivalent input encodings give identical payloads", {
  skip_if_not(CompreSSoR:::pcodec_native_available(),
              "native Pcodec backend is not built")
  variants <- ingest_variants(1200L)
  ref <- ingest_store_hashes(variants$base, "none")$payload
  for (v in c("pos_double", "pos_char", "pos_factor", "messy_alleles",
              "factor_alleles", "chr_prefix", "chr_factor", "chr_alias",
              "p_char", "p_na", "p_char_na")) {
    for (qc in c("none", "compact")) {
      expect_identical(ingest_store_hashes(variants[[v]], qc)$payload, ref,
                       label = paste(v, qc))
    }
  }
})

test_that("fast-path helpers match the character round trip", {
  slow_num <- function(x) suppressWarnings(as.numeric(as.character(x)))
  cases <- list(
    1:100, as.double(1:100), c(1, 2.5, NA, 3), c(1e15, 1), c(1e8 + 1e-8, 5),
    c(Inf, -Inf, NaN, 4), factor(c("10", "20", "x")), c("1", " 2", "3e2"),
    c(0.1 + 0.2, 1 + 1e-15), rep(c(1, NA), 50)
  )
  for (x in cases) {
    expect_identical(CompreSSoR:::coordinate_as_numeric(x), slow_num(x))
    # statistic_as_numeric() is only used for range tests: classification must agree.
    a <- CompreSSoR:::statistic_as_numeric(x); b <- slow_num(x)
    expect_identical(is.finite(a) & a > 0, is.finite(b) & b > 0)
    expect_identical(is.finite(a) & a >= 0 & a <= 1, is.finite(b) & b >= 0 & b <= 1)
  }
  alleles <- rep(c(" a", "C ", "g", "T", NA, "ac", "", " "), 20)
  slow_all <- function(x) toupper(trimws(as.character(x)))
  expect_identical(CompreSSoR:::normalise_allele_vector(alleles), slow_all(alleles))
  expect_identical(CompreSSoR:::normalise_allele_vector(factor(alleles)),
                   slow_all(factor(alleles)))
  chr <- rep(c("chr1", "CHR2", " 23", "24", "M", "x", ".", "NA", NA, ""), 10)
  slow_chr <- function(x) {
    out <- toupper(trimws(sub("^chr", "", as.character(x), ignore.case = TRUE)))
    out[out == "23"] <- "X"; out[out == "24"] <- "Y"
    out[out %in% c("M", "25", "26")] <- "MT"
    out[out %in% c("", ".", "NA")] <- NA_character_
    out
  }
  expect_identical(CompreSSoR:::normalise_chromosome(chr), slow_chr(chr))
  expect_identical(CompreSSoR:::normalise_chromosome(factor(chr)), slow_chr(chr))
  expect_error(CompreSSoR:::compressor_normalize_chromosome(rep(c("1", "MT"), 40)),
               "chromosome must be one of 1-22, X, Y")
})
